D=[]
def direction(n,title,interest,progress,nums,probs,goal,known,step):
 D.append(dict(id=f'D-SA23-hyp-{n:02}',title=title,interest=interest,feasible_progress_in_one_run=progress,items=[f'SA23-{500+i}'for i in nums],claims=[f'C-SA23-hyp-{i:03}'for i in nums],problems=[f'MP-SA23-hyp-{i:02}'for i in probs],would_establish=goal,known=known,first_step=step,development='None in this consolidation; current counterexamples and computations only check existing assertions.'))
direction(1,'Intrinsic second-order obstruction on the lci rank stratum',5,4,[89,90,97],[54,57,62],'An exact generator-independent scheme construction and the claimed ramification equality under stated base-change assumptions.','The split-kernel base-change step is valid; the second-order factorization remains expressly unverified in the draft and was not exactly matched in the sources.','Write the conormal diagram with K and W, prove invariance under one elementary generator change, and compare the resulting ideals.')
