redirects={q['original_id']:q['id'] for q in json.loads((P/'editorial_tasks.json').read_text())}
for d in D:
 d['editorial_tasks']=[redirects[q] for q in d['problems'] if q in redirects]
 d['problems']=[q for q in d['problems'] if q not in redirects]
 d['origin']='Present-run direction grounded in the cited authorial question and separately labelled editorial checks.' if d['editorial_tasks'] else 'Present-run direction grounded in the cited authorial questions.'
 assert d['problems'],d['id']+' has no authorial question'
(P/'directions.json').write_text(json.dumps(D,ensure_ascii=False,indent=2)+'\n')
lines=['# Cote25 research directions','', 'Scores are independent: interest and plausible progress in one several-hour run, each1–5. Ranking below balances both. No direction is developed here.','']
for d in D:
 lines += [f"## {d['id']}. {d['title']}",'',f"Interest **{d['interest']}/5**; one-run progress **{d['feasible_progress_in_one_run']}/5**.",'','Sources: '+', '.join(d['items']+d['claims']+d['problems']+d['editorial_tasks'])+'.','',d['origin'],'', 'Would establish: '+d['would_establish'],'','Known and residual: '+d['known'],'','First concrete step: '+d['first_step'],'']
(P/'directions.md').write_text('\n'.join(lines))
print(json.dumps({'checked_links':len(rows),'directions':len(D)}))
